html:
{#-
	Manav Sales Quotation: print format of ERPNext's Quotation, laid out like the old system's
	quotation (FMT: QUOT-11).

	Working, top to bottom:
	1. Letter head of the quotation (the principal's header), then the title.
	2. Header box: customer name, address and "Kind Attn" on the left; document number, date,
	   customer reference, sales engineer and Cust ID on the right.
	3. Items: every line that is not an option, with its code and price. A line that has
	   Specifications prints them as a table in place of its description, laid out like the
	   table on the maker's page: one specification to a row, in three columns. A line
	   "label : value 2 || value 3" fills the three cells (Haas: S.A.E. and Metric; Jagdeep:
	   Units and the model's value); "label : value" (one value only) puts the value across
	   both value columns; a line without " : " fills the whole row. A line starting with # is
	   a shaded heading row; written as "#Title || Column 2 || Column 3" it also gives the
	   titles of the two value columns. A line starting with ! is printed bold.
	   A line without Specifications prints its description, as a table too when the
	   description is written as a list:
	   - "Title; feature, feature, feature" (the Haas machines): the title is the heading row
	     and the features fill the cells below it, two to a row;
	   - several lines of which some are "label : value" (the Chmer machines): the first line
	     is the heading row and the other lines are table rows, like Specifications.
	   Any other description (a short name, a spare part) is printed as plain text.
	   Then the options of that item: the lines whose "Option of Item" is this item's code.
	4. Totals: printed only when the quotation has taxes, because the old machine quotations show
	   prices only and leave taxes to the terms.
	5. Terms and conditions (the Terms field), the signing sales person and the footer line.

	The designation under the signature is read from Employee Master through the sales person's
	old employee code.

	Created: 2026-10-12.

	CHANGE NOTE
	Date: 2026-10-13
	Change: The specifications are printed one to a row with an S.A.E. and a Metric column, and
	take the place of the item's description paragraph. Before this they were printed below the
	description, as two "label / value" pairs to a row with the Metric value only.
	Reason: The user asked for the table of the maker's page (Travels | S.A.E. | Metric) instead
	of the description paragraph.

	CHANGE NOTE
	Date: 2026-10-13
	Change: The titles of the two value columns are read from the heading line
	("#Title || Column 2 || Column 3") instead of always being S.A.E. and Metric.
	Reason: The Jagdeep site's table has the columns Description, Units and one per model, so
	its machines need other column titles than the Haas ones.

	CHANGE NOTE
	Date: 2026-10-13
	Change: A line without Specifications prints its description as a table when the
	description is a list (see point 3 above); before this it was always one paragraph.
	Reason: The user asked for the description in a proper table format when an item has no
	specifications.
-#}
{%- macro money(value) -%}{{ "%.2f"|format(value or 0) }}{%- endmacro -%}
{#- a sales person whose name was taken already is stored as "NAME (CODE)"; the code is not printed -#}
{%- macro person(name) -%}{{ (name or "").split(" (")[0] }}{%- endmacro -%}
{%- set lines = doc.get("items") or [] -%}
{%- set main_items = lines | rejectattr("custom_main_item_code") | list -%}
{%- set main_codes = main_items | map(attribute="item_code") | list -%}
{%- set signer_code = frappe.db.get_value("Sales Person", doc.custom_signed_by, "custom_employee_code") if doc.custom_signed_by else None -%}
{%- set signer_designation = frappe.db.get_value("Employee Master", signer_code, "designation") if signer_code else None -%}
{%- set contact_designation = frappe.db.get_value("Contact", doc.contact_person, "designation") if doc.contact_person else None -%}
{%- set currency = doc.currency or "" -%}

{%- macro options_table(options) -%}
	<div class="section" style="padding: 0;">
		<div class="serif" style="padding: 1px 0 1px 12%;">Options</div>
		<table class="options">
			{% for option in options %}
			<tr>
				<td style="width: 6%;" class="right">{{ loop.index }}</td>
				<td style="width: 16%;" class="small">{{ option.item_code or "" }}</td>
				<td>{{ option.description or option.item_name or "" }}</td>
				<td style="width: 18%;" class="right">{{ money(option.amount) }}</td>
			</tr>
			{% endfor %}
		</table>
	</div>
{%- endmacro -%}

<style>
	.mq { font-family: Arial, Helvetica, sans-serif; font-size: 9.5pt; color: #000; line-height: 1.35; }
	.mq table { width: 100%; border-collapse: collapse; }
	/* Frappe's print style forces 6px padding on every cell and a margin on every paragraph;
	   the !important rules below take that back so the rows sit close together. */
	.print-format .mq td, .print-format .mq th { padding: 2px 4px !important; vertical-align: top; line-height: 1.35; }
	.print-format .mq p { margin: 0 !important; }
	.mq .title { text-align: center; font-family: "Times New Roman", serif; font-size: 14pt; font-weight: bold; margin: 4px 0; }
	.mq .box { border: 1px solid #000; }
	.mq .box > tbody > tr > td { border: 1px solid #000; }
	.mq .serif { font-family: "Times New Roman", serif; font-weight: bold; font-size: 11pt; }
	.mq .head th { border: 1px solid #000; font-family: "Times New Roman", serif; font-size: 11pt; text-align: center; }
	.mq .right { text-align: right; }
	.mq .small { font-size: 8pt; }
	.mq .options td { border: 1px solid #000; }
	.mq .section { border: 1px solid #000; border-top: 0; padding: 3px 6px; }
	.mq .caps { font-weight: bold; font-size: 8.5pt; }
	.mq .item { page-break-inside: avoid; }
	.mq table.specs { margin: 2px 0 0 0; width: 100%; font-size: 8pt; page-break-inside: avoid; }
	.print-format .mq table.specs td { border: 1px solid #999; padding: 1px 4px !important; line-height: 1.3; }
	.mq .spec-heading { font-weight: bold; background: #e4e4e4; }
	.mq .spec-label { width: 46%; }
	.mq .spec-value { width: 27%; }
	.mq .spec-bold { font-weight: bold; }
	.mq .spec-feature { width: 50%; }
	.print-format .mq .terms td { padding: 1px 4px !important; border: 0; }
</style>

<div class="mq">
	{% if letter_head and not no_letterhead %}<div class="letter-head">{{ letter_head }}</div>{% endif %}
	<div class="title">Quotation</div>

	<table class="box">
		<tr>
			<td style="width: 50%;">
				<div class="serif">To</div>
				<div class="serif">{{ doc.customer_name or doc.party_name or "" }}</div>
				<div>{{ doc.address_display or "" }}</div>
				<div style="margin-top: 6px;"><b>Kind Attn :</b> &nbsp; {{ doc.contact_display or "" }} &nbsp;{{ contact_designation or "" }}</div>
			</td>
			<td style="width: 50%;">
				<table>
					<tr><td class="serif" style="width: 38%;">Document No.</td><td style="width: 4%;">:</td><td>{{ doc.name }}</td></tr>
					<tr><td class="serif">Date</td><td>:</td><td>{{ frappe.utils.formatdate(doc.transaction_date, "dd/mm/yy") if doc.transaction_date else "" }}</td></tr>
					<tr><td class="serif">Ref. No.</td><td>:</td><td>{{ doc.custom_your_reference or "" }}</td></tr>
					<tr><td class="serif">Ref Dt.</td><td>:</td><td>{{ frappe.utils.formatdate(doc.custom_your_reference_date, "dd/mm/yy") if doc.custom_your_reference_date else "" }}</td></tr>
					<tr><td class="serif">Sales Engg.</td><td>:</td><td>{{ person(doc.custom_sales_engineer) }}</td></tr>
					<tr><td class="serif">Cust ID</td><td>:</td><td>{{ doc.custom_haas_customer_id or "" }}</td></tr>
				</table>
			</td>
		</tr>
	</table>

	<table class="head" style="margin-top: -1px;">
		<tr>
			<th style="width: 8%;">Sr.No</th>
			<th style="width: 14%;">Item Code</th>
			<th>Particulars</th>
			<th style="width: 18%;">Price in {{ currency }}</th>
		</tr>
	</table>

	{% for item in main_items %}
	{% set spec_lines = (item.custom_specifications or "").split("\n") | map("trim") | select | list %}
	{#- No Specifications: see whether the description is a list that can be printed as a table.
	    The description may be stored as HTML (it is a text editor field), so paragraph ends and
	    line breaks are turned into new lines and the tags are taken out first. -#}
	{% set feature_title = "" %}
	{% set features = [] %}
	{% if not spec_lines %}
		{% set description_text = frappe.utils.strip_html((item.description or "") | replace("</p>", "\n") | replace("</div>", "\n") | replace("<br>", "\n") | replace("<br/>", "\n") | replace("<br />", "\n")) | replace("&nbsp;", " ") %}
		{% set description_lines = description_text.split("\n") | map("trim") | select | list %}
		{% if description_lines | length > 1 and " : " in (description_lines[1:] | join("\n")) %}
			{#- several lines with "label : value" among them: title line, then table rows -#}
			{% set spec_lines = ["#" ~ description_lines[0]] + description_lines[1:] %}
		{% elif description_lines %}
			{#- one sentence. "Title; a, b, c" is a title and its features. Without the "; " it is
			    only taken as a list when it has six parts or more, so that the name of a spare
			    part such as "CABLE, AXIS, BRUSHLESS" is not cut up. A comma inside a number
			    (12,000 rpm) has no space after it and does not cut. -#}
			{% set sentence = description_lines | join(" ") %}
			{% set halves = sentence.split("; ", 1) %}
			{% set parts = (halves | last | replace("; ", ", ")).split(", ") | map("trim") | select | list %}
			{% if halves | length > 1 and parts | length >= 3 %}
				{% set feature_title = halves[0] | trim %}
				{% set features = parts %}
			{% elif halves | length == 1 and parts | length >= 6 %}
				{% set feature_title = parts[0] %}
				{% set features = parts[1:] %}
			{% endif %}
		{% endif %}
	{% endif %}
	<div class="section">
		<table class="item">
			<tr>
				<td style="width: 8%;" class="right">{{ "%02d"|format(loop.index) }}</td>
				<td style="width: 14%;" class="serif">{{ item.item_code or "" }}</td>
				{# a table below (specifications, or the description as a table) stands in for the paragraph #}
				<td class="serif">{% if not spec_lines and not features %}{{ item.description or item.item_name or "" }}{% endif %}
					{%- if frappe.utils.flt(item.qty) != 1 %} &nbsp; ({{ item.qty | round(2) }} {{ item.uom or "" }} x {{ money(item.rate) }}){% endif %}</td>
			</tr>
		</table>

		{% if features %}
		<table class="specs">
			<tr><td colspan="2" class="spec-heading">{{ feature_title }}</td></tr>
			{% for pair in features | batch(2) %}
			<tr>
				{% for feature in pair %}<td class="spec-feature">{{ feature }}</td>{% endfor %}
				{% if pair | length == 1 %}<td class="spec-feature"></td>{% endif %}
			</tr>
			{% endfor %}
		</table>
		{% endif %}

		{# Specification lines of this item, one to a row: label, S.A.E. value, Metric value.
		   The text is cut at every line that starts with #: each piece is one block, whose first
		   line (except in the piece before the first #) is the block's heading. The two values of
		   a line, and the column titles in a heading, are separated by " || " (written by the
		   Format buttons on the Item). #}
		{% for block in ("\n" ~ (spec_lines | join("\n"))).split("\n#") %}
		{% set block_lines = block.split("\n") | map("trim") | select | list %}
		{% set heading = None if loop.first else (block_lines | first) %}
		{% set specs = block_lines if loop.first else block_lines[1:] %}
		{# a heading "Title || Column 2 || Column 3" also names the two value columns #}
		{% set titles = (heading or "").split(" || ") | map("trim") | list %}
		{% if heading or specs %}
		<table class="specs">
			{% if titles | length > 2 %}
			<tr><td class="spec-label spec-heading">{{ titles[0] }}</td><td class="spec-value spec-heading">{{ titles[1] }}</td><td class="spec-value spec-heading">{{ titles[2] }}</td></tr>
			{% elif heading %}
			<tr><td colspan="3" class="spec-heading">{{ heading }}</td></tr>
			{% endif %}
			{% for spec in specs %}
			{% set bold = spec.startswith("!") %}
			{% set text = (spec[1:] if bold else spec) | trim %}
			{% set cells = text.split(" : ", 1) %}
			<tr{% if bold %} class="spec-bold"{% endif %}>
				{% if cells | length == 2 %}
				{% set units = cells[1].split(" || ", 1) %}
				<td class="spec-label">{{ cells[0] | trim }}</td>
				{% if units | length == 2 %}
				<td class="spec-value">{{ units[0] | trim }}</td>
				<td class="spec-value">{{ units[1] | trim }}</td>
				{% else %}
				<td colspan="2">{{ cells[1] | trim }}</td>
				{% endif %}
				{% else %}
				<td colspan="3">{{ text }}</td>
				{% endif %}
			</tr>
			{% endfor %}
		</table>
		{% endif %}
		{% endfor %}

		<table>
			<tr>
				<td style="padding-left: 8%;"><b>Price :</b></td>
				<td class="right" style="width: 10%;"><b>{{ currency }}</b></td>
				<td class="right" style="width: 18%;"><b>{{ money(item.amount) }}</b></td>
			</tr>
		</table>
	</div>

	{% set options = lines | selectattr("custom_main_item_code", "equalto", item.item_code) | list %}
	{% if options %}{{ options_table(options) }}{% endif %}
	{% endfor %}

	{# options whose machine is not among the items of the quotation #}
	{% set other_options = lines | selectattr("custom_main_item_code") | rejectattr("custom_main_item_code", "in", main_codes) | list %}
	{% if other_options %}{{ options_table(other_options) }}{% endif %}

	{# totals only when there are taxes to show #}
	{% if frappe.utils.flt(doc.total_taxes_and_charges) %}
	<div class="section">
		<table>
			<tr><td class="right"><b>Total</b></td><td class="right" style="width: 18%;">{{ money(doc.net_total) }}</td></tr>
			{% for tax in doc.taxes %}{% if frappe.utils.flt(tax.tax_amount) %}
			<tr><td class="right">{{ tax.description or tax.account_head or "" }}{% if frappe.utils.flt(tax.rate) %} @ {{ tax.rate | round(2) }}%{% endif %}</td><td class="right">{{ money(tax.tax_amount) }}</td></tr>
			{% endif %}{% endfor %}
			<tr><td class="right"><b>Grand Total ({{ currency }})</b></td><td class="right"><b>{{ money(doc.grand_total) }}</b></td></tr>
		</table>
	</div>
	{% endif %}

	{% if doc.terms %}
	<div class="section terms">
		<div class="caps">TERMS AND CONDITIONS</div>
		{{ doc.terms }}
	</div>
	{% endif %}

	<div class="section" style="page-break-inside: avoid;">
		<div class="caps">For {{ doc.company or "Manav Marketing Pvt. Ltd." }}</div>
		<div style="height: 42px;"></div>
		<div>{{ person(doc.custom_signed_by) }}</div>
		<div>{{ signer_designation or "" }}</div>
	</div>
	<table class="box" style="margin-top: -1px;">
		<tr>
			<td style="width: 14%;" class="small">FMT: QUOT-11</td>
			<td class="small">CC : &nbsp;{{ person(doc.custom_sales_engineer) }}</td>
			<td style="width: 28%;" class="small right">E &amp; O.E</td>
		</tr>
	</table>
</div>
{#- 2026-11-03: "Page n of m" at the foot of every page of the PDF (the user's request) -#}
{% include "manav/templates/print_formats/manav_page_number.html" %}
